from pathlib import Path
import json,html,hashlib
O=Path(__file__).resolve().parent
load=lambda n:json.loads((O/n).read_text()) if (O/n).exists() else None
replay=load('replay-check.json');sampling=load('sampling-check.json');comparison=load('checkpoint-comparison.json')
rollouts=[]
for p in sorted(O.glob('results-*.json')):rollouts.extend(json.loads(p.read_text()))
summary=dict(replay=replay,prefix_sensitivity=load('prefix-check.json'),samplers=sampling,checkpoint_comparison=comparison,failure_details=load('final-failure-details.json'),rollouts=rollouts,one_episode_status=load('single-run/status.json'),one_episode_spec=load('single-run/spec.json'),limitations=['Small diagnostic subsets; same capture session, not independent-layout generalization.','Replay warmup injects recorded states only during the prefix, then free-runs. It is not autonomous from time zero.','Learned rollouts use cold lower-controller history; first train and first valid starts have successful recorded-command controls.','Host inference pauses simulated time; Quest latency not represented.','Generated-action errors are not joint tracking errors or task success rates.'],deployment=False,production_source_changed=False)
(O/'summary.json').write_text(json.dumps(summary,indent=2))
def table(head,rows):return '<table><tr>'+''.join('<th>'+html.escape(str(x))+'</th>' for x in head)+'</tr>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in r)+'</tr>' for r in rows)+'</table>'
bits=['<h1>Проверка обучения чашки · 15 октября</h1>','<p>Диагностика сохранена отдельно; текущий APK, исходные веса и DexWeave не менялись.</p>','<h2>История нижнего контроллера</h2>','<p>Контроль исходными командами на четырёх validation-стартах: с пустой историей 2/4 успеха, с префиксом 0,5 с — 3/4. В префиксе подставляются записанные физические состояния для восстановления истории HOMIE, затем симуляция идёт свободно. Четвёртый старт не проходит и с префиксами 0,8 и 1 с. Точное воспроизведение всей записи пока не подтверждено.</p>']
if comparison:
 bits+=['<h2>Выбор весов</h2>','<p>12 окон на первых четырёх train и 12 на четырёх valid, по 48 будущих команд. Одинаковая диагностика на GPU. Ошибка усреднена по 14 командам суставов рук; Grip — по двум каналам. Выбор по validation noise MSE пропустил более точные финальные веса. Это ещё не доказательство успеха задачи.</p>',table(['Веса','Набор','Руки, ° MAE','Grip MAE'],[(Path(r['checkpoint']).parent.name+'/'+Path(r['checkpoint']).name+' '+r['weights'],r['split'],round(r['arms_deg'],2),round(r['grip_mae'],4)) for r in comparison])]
if sampling:bits+=['<h2>Диффузионный вывод ранних весов</h2>','<p>12 validation-окон, один seed. DDPM50 уменьшает ошибку, DDIM50 почти не меняет результат. Это отдельная проверка; числа нельзя напрямую сравнивать с другой случайной выборкой шума/GPU.</p>',table(['Sampler','Шаги','Руки, ° MAE','Grip MAE'],[(r['sampler'],r['steps'],round(r['arms_deg'],2),round(r['grip_mae'],4)) for r in sampling])]
if summary['one_episode_status']:
 s=summary['one_episode_status'];bits+=['<h2>Одна учебная траектория</h2>',f'<p>Свежий U-Net + публичный R3M, без аугментаций и шума команд, {s["step"]} обновлений. На шести учебных окнах: raw {s["raw"]["arms_deg"]:.2f}°, EMA {s["ema"]["arms_deg"]:.2f}°. Обучение ещё не достигло точного запоминания; этот короткий запуск не доказывает неисправность обучения. Отдельно финальная модель полного обучения уже воспроизводит выбранные train-команды примерно с ошибкой 1°.</p>']
if (O/'early-vs-final-train.mp4').exists():bits+=['<h2>Ранние и финальные веса: один train-старт</h2><p>3D-воспроизведение автономных прогонов, не экран Quest. Слева epoch15, справа epoch300. После успеха на 8,7 с правая сторона удерживает последний кадр.</p><video controls style="width:100%" src="early-vs-final-train.mp4"></video>']
if rollouts:bits+=['<h2>Проверка в физике</h2>','<p>Seed 0, до 90 с на попытку. 48 команд между наблюдениями = 1,6 с; 8 = 0,267 с. Записанные состояния после старта в эти прогоны не подставляются.</p>',table(['Веса','Эпизод','Шагов','Успех','Время, с','Подъём, см','Ошибка XY, см'],[(r['label'],r['episode'],r['execution_steps'],r['success'],round(r['elapsed_sim_s'],1),round(r['lift_m']*100,1),round(r['final_goal_xy_error_m']*100,1)) for r in rollouts])]
bits+=['<h2>Почему не прошли длинные блоки</h2><p>Финальные веса с блоком 48: все четыре validation-прогона закончились чашкой на боку (вертикальная компонента оси около 0,001, нужно &gt;0,94). В трёх не выполнен квалифицируемый подъём &gt;4,5 см. Это наблюдаемые исходы, а не доказательство единственной причины ошибки.</p><h2>Ограничения</h2><p>Малые диагностические подвыборки одной сессии. Скрытая история при старте learned-rollout пустая; контроль на выбранных первых train/valid стартах проходит. Вычисление модели приостанавливает физику; задержка на Quest не измеряется. Ниже ссылки на исходные результаты.</p>','<p><a href="summary.json">Все метрики</a> · <a href="evaluate.py">Автономная проверка</a> · <a href="check_replay.py">Контроль воспроизведения</a> · <a href="one_episode.py">Обучение одной траектории</a></p>']
(O/'REPORT.html').write_text('<!doctype html><html lang="ru"><meta charset="utf-8"><title>Проверка обучения чашки</title><style>body{font:16px system-ui;max-width:1120px;margin:40px auto;padding:0 24px;background:#10151f;color:#edf2f9;line-height:1.5}table{border-collapse:collapse;font-size:14px;width:100%;overflow:auto;display:block}td,th{padding:9px;border:1px solid #354157;text-align:left}h2{margin-top:32px}a{color:#89c8ff}</style>'+''.join(bits)+'</html>')
